unicorn_colossus.source:
export const envelope = [25, 38, 27];

export default function build(api) {
  const [W, H, D] = api.size;

  // Theme-derived palette roles with safe fallbacks
  const stonePrimary = api.theme?.stone?.primary || "minecraft:quartz_block";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:quartz_bricks";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:quartz_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:quartz_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:diorite_wall";
  const groundPlinth = api.theme?.ground?.plinth || "minecraft:smooth_quartz";
  const groundPavement = api.theme?.ground?.pavement || "minecraft:quartz_pillar";

  // Arcane & celestial materials for the colossus and amethyst horn
  const amethystBlock = "minecraft:amethyst_block";
  const buddingAmethyst = "minecraft:budding_amethyst";
  const amethystCluster = "minecraft:amethyst_cluster";
  const seaLantern = "minecraft:sea_lantern";
  const calcite = "minecraft:calcite";
  const smoothQuartz = "minecraft:smooth_quartz";
  const quartzPillar = "minecraft:quartz_pillar";
  const chiseledQuartz = "minecraft:chiseled_quartz_block";
  const goldBlock = "minecraft:gold_block";
  const tintedGlass = "minecraft:tinted_glass";

  // Helper block state builders
  function stair(baseStair, facing, half = "bottom") {
    const b = baseStair.split("[")[0];
    return `${b}[facing=${facing},half=${half}]`;
  }
  function slab(baseSlab, type = "bottom") {
    const b = baseSlab.split("[")[0];
    return `${b}[type=${type}]`;
  }
  function pillar(basePillar, axis = "y") {
    const b = basePillar.split("[")[0];
    return `${b}[axis=${axis}]`;
  }

  // 3D Voxel buffer
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function set(x, y, z, block, overwrite = true) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    if (!overwrite && grid[x][y][z] !== null) return;
    grid[x][y][z] = block;
  }

  // -------------------------------------------------------------
  // 1. MONUMENTAL PLINTH & SANCTUARY VAULT (Y: 0 to 7)
  // -------------------------------------------------------------
  const cx = 12;
  const cz = 13;

  for (let x = 2; x <= 22; x++) {
    for (let z = 2; z <= 24; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      const distCorner = dx + dz;

      // Octagonal plinth footprint
      if (dx <= 9 && dz <= 10 && distCorner <= 14) {
        // Floor at Y = 0
        if (x >= 8 && x <= 16 && z >= 8 && z <= 18) {
          // Sanctuary Floor
          const distToCenter = Math.hypot(x - cx, z - cz);
          if (distToCenter < 1.2) {
            set(x, 0, z, seaLantern);
          } else if (distToCenter < 2.5) {
            set(x, 0, z, amethystBlock);
          } else {
            set(x, 0, z, smoothQuartz);
          }
        } else if (x >= 10 && x <= 14 && z >= 2 && z <= 7) {
          // Grand Entrance Corridor Floor
          set(x, 0, z, (x === 12) ? smoothQuartz : groundPavement);
        } else {
          // Outer Plinth Rim Floor
          set(x, 0, z, groundPlinth);
        }

        // Walls (Y = 1 to 5)
        const isSanctuaryInterior = (x >= 8 && x <= 16 && z >= 8 && z <= 18);
        const isEntranceCorridor = (x >= 10 && x <= 14 && z >= 2 && z <= 7);

        // Sanctuary Corner Columns
        const isPillar = (
          (x === 8 && z === 8) || (x === 16 && z === 8) ||
          (x === 8 && z === 18) || (x === 16 && z === 18)
        );

        if (isPillar) {
          for (let y = 1; y <= 5; y++) {
            if (y === 1) set(x, y, z, chiseledQuartz);
            else if (y === 5) set(x, y, z, chiseledQuartz);
            else set(x, y, z, pillar(quartzPillar, "y"));
          }
        } else if (!isSanctuaryInterior && !isEntranceCorridor) {
          // Plinth perimeter masonry
          for (let y = 1; y <= 5; y++) {
            // Buttress accents at outer corners
            const isButtress = (
              (x <= 4 && z <= 5) || (x >= 20 && z <= 5) ||
              (x <= 4 && z >= 21) || (x >= 20 && z >= 21)
            );

            if (isButtress) {
              if (y === 3) set(x, y, z, seaLantern);
              else if (y === 1 || y === 5) set(x, y, z, stoneAccent);
              else set(x, y, z, pillar(quartzPillar, "y"));
            } else if ((x === 2 || x === 22) && (z >= 12 && z <= 14)) {
              // Side arcane stained windows
              if (y === 3) set(x, y, z, tintedGlass);
              else set(x, y, z, stonePrimary);
            } else if (z === 24 && x >= 11 && x <= 13) {
              // Rear shrine niche
              if (y === 2 || y === 3) set(x, y, z, amethystBlock);
              else set(x, y, z, stoneAccent);
            } else {
              set(x, y, z, (y % 2 === 0) ? stoneAccent : stonePrimary);
            }
          }
        }

        // Grand Portal Jambs & Arch (North Face: Z = 2 to 4, X = 9 and 15)
        if ((x === 9 || x === 15) && (z >= 2 && z <= 4)) {
          for (let y = 1; y <= 5; y++) {
            set(x, y, z, pillar(quartzPillar, "y"));
          }
        }
        if (z === 2 && (x >= 10 && x <= 14)) {
          set(x, 5, z, (x === 12) ? amethystBlock : stair(stoneStairs, (x < 12) ? "east" : "west", "top"));
        }

        // Ceiling Vault (Y = 6)
        if (isSanctuaryInterior) {
          if (x === cx && z === cz) {
            set(x, 6, z, seaLantern);
          } else {
            set(x, 6, z, smoothQuartz);
          }
        } else {
          set(x, 6, z, stonePrimary);
        }

        // Corbelled Cornice along Plinth Rim (Y = 6)
        if (dx >= 8 || dz >= 9 || distCorner >= 13) {
          let facing = "north";
          if (z > cz) facing = "south";
          if (dx > dz) facing = (x > cx) ? "east" : "west";
          set(x, 6, z, stair(stoneStairs, facing, "top"));
        }

        // Top Deck Surface (Y = 7)
        set(x, 7, z, ((x + z) % 2 === 0) ? smoothQuartz : calcite);

        // Deck Parapet (Y = 8)
        if (dx === 9 || dz === 10 || distCorner === 14) {
          set(x, 8, z, stoneWall);
        }
      }
    }
  }

  // Four Corner Arcane Braziers on the Deck
  const brazierCoords = [[4, 4], [20, 4], [4, 22], [20, 22]];
  for (const [bx, bz] of brazierCoords) {
    set(bx, 8, bz, stoneAccent);
    set(bx, 9, bz, seaLantern);
    set(bx, 10, bz, amethystCluster);
  }

  // -------------------------------------------------------------
  // 2. THE UNICORN COLOSSUS (Y: 8 to 37)
  // -------------------------------------------------------------

  // A. Four Majestic Hooves & Fetlocks (Y = 8 to 10)
  const hooves = [
    { x: 8.5, z: 7.5 },   // Front-Left
    { x: 15.5, z: 7.5 },  // Front-Right
    { x: 8.5, z: 18.5 },  // Rear-Left
    { x: 15.5, z: 18.5 }, // Rear-Right
  ];

  for (const h of hooves) {
    for (let x = Math.floor(h.x - 2); x <= Math.ceil(h.x + 2); x++) {
      for (let z = Math.floor(h.z - 2); z <= Math.ceil(h.z + 2); z++) {
        const d = Math.hypot(x - h.x, z - h.z);
        if (d <= 1.8) set(x, 8, z, goldBlock);
        if (d <= 1.4) set(x, 9, z, (d <= 0.8) ? amethystBlock : goldBlock);
        if (d <= 1.3) set(x, 10, z, calcite);
      }
    }
  }

  // B. Forelegs (Y = 11 to 17)
  for (let y = 11; y <= 17; y++) {
    const t = (y - 11) / 6.0;
    const flx = 8.5 - 0.3 * t;
    const flz = 7.5 + 0.3 * t;
    const frx = 15.5 + 0.3 * t;
    const frz = 7.5 + 0.3 * t;
    const rad = (y < 14) ? 1.25 : 1.25 + 0.6 * ((y - 14) / 3.0);

    for (let x = 6; x <= 18; x++) {
      for (let z = 5; z <= 10; z++) {
        const dL = Math.hypot(x - flx, z - flz);
        const dR = Math.hypot(x - frx, z - frz);
        if (dL <= rad || dR <= rad) {
          set(x, y, z, (y === 14) ? calcite : smoothQuartz);
        }
      }
    }
  }

  // C. Hindlegs & Muscular Hocks (Y = 11 to 17)
  for (let y = 11; y <= 17; y++) {
    const t = (y - 11) / 6.0;
    const rlx = 8.5 - 0.4 * t;
    const rlz = 18.5 + 1.2 * Math.sin(t * Math.PI);
    const rrx = 15.5 + 0.4 * t;
    const rrz = 18.5 + 1.2 * Math.sin(t * Math.PI);
    const rad = 1.3 + 1.2 * (t * t);

    for (let x = 6; x <= 18; x++) {
      for (let z = 16; z <= 22; z++) {
        const dL = Math.hypot(x - rlx, z - rlz);
        const dR = Math.hypot(x - rrx, z - rrz);
        if (dL <= rad || dR <= rad) {
          set(x, y, z, (t > 0.6) ? calcite : smoothQuartz);
        }
      }
    }
  }

  // D. Torso & Muscular Barrel (Y = 16 to 25, Z = 6 to 21)
  for (let z = 6; z <= 21; z++) {
    const t = (z - 6) / 15.0; // 0 at chest, 1 at rump
    const spineY = 20.2 - 1.2 * Math.sin(t * Math.PI) + 0.4 * Math.cos(t * Math.PI * 2);
    const rx = 3.2 + 0.8 * Math.sin(t * Math.PI);
    const ry = 3.8 - 0.5 * t + 0.5 * Math.sin(t * Math.PI);

    for (let x = 6; x <= 18; x++) {
      for (let y = 15; y <= 25; y++) {
        const dx = (x - cx) / rx;
        const dy = (y - spineY) / ry;
        if (dx * dx + dy * dy <= 1.0) {
          // Chest astral emblem facing North
          if (z <= 7 && Math.abs(x - cx) <= 1 && Math.abs(y - 20) <= 1) {
            if (x === cx && y === 20 && z === 6) {
              set(x, y, z, seaLantern);
            } else {
              set(x, y, z, goldBlock);
            }
          } else if (y >= spineY + ry * 0.7 && Math.abs(x - cx) <= 0.9) {
            // Dorsal spine crystal ridge
            set(x, y, z, amethystBlock);
          } else if ((x + y + z) % 5 === 0) {
            set(x, y, z, calcite);
          } else {
            set(x, y, z, smoothQuartz);
          }
        }
      }
    }
  }

  // E. Gracefully Arching Neck (Y = 20 to 30, Z = 3 to 10)
  for (let y = 20; y <= 30; y++) {
    const t = (y - 20) / 10.0;
    const neckZ = 8.5 * (1.0 - t) + 4.2 * t - 0.4 * Math.sin(t * Math.PI);
    const rx = 2.4 * (1.0 - 0.35 * t);
    const rz = 2.8 * (1.0 - 0.25 * t);

    for (let x = 9; x <= 15; x++) {
      for (let z = 2; z <= 11; z++) {
        const dx = (x - cx) / rx;
        const dz = (z - neckZ) / rz;
        if (dx * dx + dz * dz <= 1.0) {
          if (z >= neckZ + rz * 0.7 && Math.abs(x - cx) <= 0.8) {
            set(x, y, z, amethystBlock);
          } else if ((x + y + z) % 4 === 0) {
            set(x, y, z, calcite);
          } else {
            set(x, y, z, smoothQuartz);
          }
        }
      }
    }
  }

  // F. Noble Head & Muzzle (Y = 27 to 33, Z = 1 to 7)
  // Cranium
  for (let x = 10; x <= 14; x++) {
    for (let y = 29; y <= 33; y++) {
      for (let z = 3; z <= 6; z++) {
        const dx = (x - cx) / 1.9;
        const dy = (y - 31.0) / 1.8;
        const dz = (z - 4.5) / 1.9;
        if (dx * dx + dy * dy + dz * dz <= 1.0) {
          set(x, y, z, smoothQuartz);
        }
      }
    }
  }

  // Glowing Celestial Eyes
  set(10, 30, 3, seaLantern);
  set(14, 30, 3, seaLantern);
  set(10, 31, 3, smoothQuartz);
  set(14, 31, 3, smoothQuartz);

  // Muzzle & Nostrils
  for (let z = 1; z <= 4; z++) {
    const t = (4.0 - z) / 3.0;
    const snoutY = 29.5 - 1.5 * t;
    const rx = 1.6 * (1.0 - 0.4 * t);
    const ry = 1.5 * (1.0 - 0.35 * t);

    for (let x = 10; x <= 14; x++) {
      for (let y = 27; y <= 31; y++) {
        const dx = (x - cx) / rx;
        const dy = (y - snoutY) / ry;
        if (dx * dx + dy * dy <= 1.0) {
          if (z === 1 && (x === 11 || x === 13) && y === 28) {
            set(x, y, z, chiseledQuartz);
          } else if (z === 1) {
            set(x, y, z, calcite);
          } else {
            set(x, y, z, smoothQuartz);
          }
        }
      }
    }
  }

  // Upright Alert Ears
  set(10, 33, 5, smoothQuartz);
  set(10, 34, 5, smoothQuartz);
  set(9, 35, 5, amethystBlock);
  set(14, 33, 5, smoothQuartz);
  set(14, 34, 5, smoothQuartz);
  set(15, 35, 5, amethystBlock);

  // G. The Celestial Amethyst Spiral Horn (Y = 31 to 37, Z = 0 to 4)
  for (let s = 0; s <= 1.0; s += 0.02) {
    const hy = 31.5 + s * 5.5;
    const hz = 3.8 - s * 3.6;
    const spiralAngle = s * Math.PI * 5.0;
    const spiralRad = 0.35 * (1.0 - s * 0.7);
    const hx = cx + spiralRad * Math.sin(spiralAngle);
    const hzSpiral = hz + spiralRad * Math.cos(spiralAngle);
    const coreRad = 1.3 * (1.0 - s * 0.82);

    const minX = Math.floor(hx - coreRad);
    const maxX = Math.ceil(hx + coreRad);
    const minY = Math.floor(hy - coreRad);
    const maxY = Math.ceil(hy + coreRad);
    const minZ = Math.floor(hzSpiral - coreRad);
    const maxZ = Math.ceil(hzSpiral + coreRad);

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const d2 = (
            Math.pow((x - hx) / coreRad, 2) +
            Math.pow((y - hy) / coreRad, 2) +
            Math.pow((z - hzSpiral) / coreRad, 2)
          );
          if (d2 <= 1.0) {
            let mat = amethystBlock;
            if (s > 0.88) {
              mat = (y >= 37) ? amethystCluster : buddingAmethyst;
            } else if (s > 0.5) {
              mat = (Math.sin(s * 20.0) > 0.3) ? buddingAmethyst : amethystBlock;
            } else if (s < 0.15) {
              mat = calcite;
            }
            set(x, y, z, mat);
          }
        }
      }
    }
  }
  set(cx, 37, 0, amethystCluster);

  // H. Billowing Celestial Mane (Y = 21 to 33)
  for (let y = 21; y <= 33; y++) {
    const t = (y - 20) / 13.0;
    const neckZ = 8.5 * (1.0 - (y - 20) / 10.0) + 4.2 * ((y - 20) / 10.0);
    const crestZ = neckZ + 1.2;
    const wave = Math.sin(t * Math.PI * 2.5);
    const mx = cx + 1.2 * wave;
    const mz = crestZ + 0.8 + 0.5 * Math.cos(t * Math.PI * 2.0);

    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = 0; dz <= 2; dz++) {
        const vx = Math.round(mx + dx);
        const vz = Math.round(mz + dz);
        if (Math.abs(vx - cx) <= 2 && vz <= 12) {
          const mat = (dz === 2 || (y % 3 === 0)) ? amethystBlock : ((y % 2 === 0) ? calcite : smoothQuartz);
          set(vx, y, vz, mat);
        }
      }
    }
  }

  // I. Sweeping Celestial Wings along Flanks
  for (const side of [-1, 1]) {
    for (let u = 0; u <= 1.0; u += 0.03) {
      const wx = cx + side * (3.5 + 7.5 * Math.sin(u * Math.PI * 0.85));
      const wy = 21.0 + 12.5 * Math.sin(u * 1.15);
      const wz = 9.0 + 13.5 * u;
      const rad = 1.4 * (1.0 - u * 0.45);

      for (let feather = 0; feather <= 3; feather++) {
        const fy = wy - feather * 0.9;
        const fz = wz + feather * 0.4;
        const fx = wx - side * feather * 0.3;

        const minX = Math.floor(fx - rad);
        const maxX = Math.ceil(fx + rad);
        const minY = Math.floor(fy - rad);
        const maxY = Math.ceil(fy + rad);
        const minZ = Math.floor(fz - rad);
        const maxZ = Math.ceil(fz + rad);

        for (let x = minX; x <= maxX; x++) {
          for (let y = minY; y <= maxY; y++) {
            for (let z = minZ; z <= maxZ; z++) {
              const d = Math.pow(x - fx, 2) + Math.pow(y - fy, 2) + Math.pow(z - fz, 2);
              if (d <= rad * rad) {
                let mat = smoothQuartz;
                if (u > 0.8 || feather === 3) mat = amethystBlock;
                else if (u > 0.5 || feather === 2) mat = calcite;
                else if (feather === 0) mat = stoneAccent;
                set(x, y, z, mat);
              }
            }
          }
        }
      }
    }
  }

  // J. Plumed Cascading Tail (Y = 8 to 23, Z = 21 to 26)
  for (let t = 0; t <= 1.0; t += 0.02) {
    const ty = 21.5 + 2.0 * Math.sin(t * Math.PI * 0.6) - 14.5 * t;
    const tz = 21.0 + 4.5 * Math.sin(t * Math.PI * 0.85);
    const tx = cx + 1.2 * Math.sin(t * Math.PI * 2.0);
    const rad = 1.5 * (1.0 - 0.4 * t);

    const minX = Math.floor(tx - rad);
    const maxX = Math.ceil(tx + rad);
    const minY = Math.floor(ty - rad);
    const maxY = Math.ceil(ty + rad);
    const minZ = Math.floor(tz - rad);
    const maxZ = Math.ceil(tz + rad);

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const d = Math.pow(x - tx, 2) + Math.pow(y - ty, 2) + Math.pow(z - tz, 2);
          if (d <= rad * rad) {
            const mat = (t > 0.7 || (x + y) % 3 === 0) ? amethystBlock : ((y % 2 === 0) ? calcite : smoothQuartz);
            set(x, y, z, mat);
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 3. FLUSH VOXEL BUFFER DETERMINISTICALLY
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Celestial Unicorn Colossus",
    seatY: 0,
    anchors: {
      front: [12, 0, 0],
      door: [12, 1, 2],
    },
    interiors: [
      {
        min: [8, 1, 8],
        max: [16, 5, 18],
        kind: "sanctuary",
      },
    ],
  };
}

pirate_skull_fort.source:
export const envelope = [26, 32, 26];

export default function build(api) {
  const W = envelope[0];
  const H = envelope[1];
  const D = envelope[2];
  const seatY = 4;

  // Resolve palette roles from the settlement theme with pirate/stone defaults
  const stonePrimary = api.theme.stone.primary || "minecraft:blackstone";
  const stoneAccent = api.theme.stone.accent || "minecraft:polished_blackstone_bricks";
  const stoneStairs = api.theme.stone.stairs || "minecraft:blackstone_stairs";
  const stoneSlab = api.theme.stone.slab || "minecraft:blackstone_slab";
  const stoneWall = api.theme.stone.wall || "minecraft:blackstone_wall";

  const woodPlanks = api.theme.wood.planks || "minecraft:dark_oak_planks";
  const woodLog = api.theme.wood.log || "minecraft:dark_oak_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_dark_oak_log";
  const woodStairs = api.theme.wood.stairs || "minecraft:dark_oak_stairs";
  const woodFence = api.theme.wood.fence || "minecraft:dark_oak_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:dark_oak_trapdoor";

  const groundPlinth = api.theme.ground.plinth || stonePrimary;
  const groundPavement = api.theme.ground.pavement || "minecraft:polished_blackstone";
  const wallMerlon = api.theme.wall.merlon || stoneWall;

  // 3D voxel grid buffer
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function isFortFootprint(x, z) {
    const dxCranium = (x - 12.5) / 10.0;
    const dzCranium = (z - 14.0) / 9.5;
    if (dxCranium * dxCranium + dzCranium * dzCranium <= 1.0) return true;

    // Jaw base extending forward
    if (x >= 7 && x <= 18 && z >= 2 && z <= 10) return true;

    // Rear watchtowers
    const dTowerL = (x - 5) ** 2 + (z - 18) ** 2;
    if (dTowerL <= 3.8 ** 2) return true;
    const dTowerR = (x - 20) ** 2 + (z - 18) ** 2;
    if (dTowerR <= 3.8 ** 2) return true;

    // Rear wall connection
    if (x >= 5 && x <= 20 && z >= 17 && z <= 22) return true;

    return false;
  }

  // 1. Footing & Foundation downwards into terrain
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isFortFootprint(x, z)) {
        const h = api.heightAt(x, z);
        const groundH = Math.max(0, Math.min(seatY, Math.floor(seatY + h)));
        for (let y = groundH; y <= seatY; y++) {
          setBlock(x, y, z, y === seatY ? groundPlinth : stonePrimary);
        }
      }
    }
  }

  // 2. Primary Solid Geometry (Cranium, Jaw, Cheekbones, Towers, Bastion Walls)
  for (let x = 0; x < W; x++) {
    for (let y = seatY; y < H; y++) {
      for (let z = 0; z < D; z++) {
        // Cranium Ellipsoid
        const dx = (x - 12.5) / 9.5;
        const dy = (y - 20.0) / 7.5;
        const dz = (z - 14.0) / 9.0;
        const inCranium = dx * dx + dy * dy + dz * dz <= 1.0;

        // Snout / Maxilla / Mandible (Skull Jaw)
        const jx = (x - 12.5) / 5.8;
        const jy = (y - 9.5) / 5.0;
        const jz = (z - 6.0) / 4.5;
        const inJaw = jx * jx + jy * jy + jz * jz <= 1.0 && y >= seatY && y <= 15 && z <= 10;

        // Cheekbones (Zygomatic Arches)
        const cx1 = (x - 4.5) / 2.2;
        const cy1 = (y - 15.0) / 2.8;
        const cz1 = (z - 9.5) / 3.8;
        const inCheekL = cx1 * cx1 + cy1 * cy1 + cz1 * cz1 <= 1.0;

        const cx2 = (x - 20.5) / 2.2;
        const cy2 = (y - 15.0) / 2.8;
        const cz2 = (z - 9.5) / 3.8;
        const inCheekR = cx2 * cx2 + cy2 * cy2 + cz2 * cz2 <= 1.0;

        // Rear Defensive Watchtowers
        const inTowerL = (x - 5) ** 2 + (z - 18) ** 2 <= 3.5 ** 2 && y >= seatY && y <= 28;
        const inTowerR = (x - 20) ** 2 + (z - 18) ** 2 <= 3.5 ** 2 && y >= seatY && y <= 28;

        // Rear Curtain Wall
        const inRearWall = x >= 5 && x <= 20 && z >= 18 && z <= 21 && y >= seatY && y <= 22;

        if (inCranium || inJaw || inCheekL || inCheekR || inTowerL || inTowerR || inRearWall) {
          const isAccent = (x * 3 + y * 7 + z * 5) % 9 === 0;
          setBlock(x, y, z, isAccent ? stoneAccent : stonePrimary);
        }
      }
    }
  }

  // 3. Carve Interiors, Gunports, and Cranial Openings
  // Lower Barracks / Hold
  for (let x = 8; x <= 17; x++) {
    for (let y = seatY + 1; y <= 9; y++) {
      for (let z = 8; z <= 18; z++) {
        setBlock(x, y, z, null);
      }
    }
  }
  // Mouth Tunnel Gateway
  for (let x = 10; x <= 15; x++) {
    for (let y = seatY + 1; y <= 9; y++) {
      for (let z = 1; z <= 8; z++) {
        setBlock(x, y, z, null);
      }
    }
  }

  // Upper Battery Deck Interior
  for (let x = 7; x <= 18; x++) {
    for (let y = 15; y <= 20; y++) {
      for (let z = 8; z <= 18; z++) {
        setBlock(x, y, z, null);
      }
    }
  }

  // Eye Sockets (Deep Gunports)
  for (let y = 15; y <= 19; y++) {
    for (let z = 1; z <= 7; z++) {
      for (let x = 7; x <= 10; x++) {
        const ex = (x - 8.5) / 2.0;
        const ey = (y - 17.0) / 2.0;
        if (ex * ex + ey * ey <= 1.0) setBlock(x, y, z, null);
      }
      for (let x = 15; x <= 18; x++) {
        const ex = (x - 16.5) / 2.0;
        const ey = (y - 17.0) / 2.0;
        if (ex * ex + ey * ey <= 1.0) setBlock(x, y, z, null);
      }
    }
  }

  // Nasal Cavity (Nose Aperture)
  for (let z = 2; z <= 6; z++) {
    for (let x = 11; x <= 14; x++) {
      for (let y = 11; y <= 14; y++) {
        if (y === 11 && (x === 12 || x === 13)) setBlock(x, y, z, null);
        if (y === 12 || y === 13) setBlock(x, y, z, null);
        if (y === 14 && (x === 12 || x === 13)) setBlock(x, y, z, null);
      }
    }
  }

  // Sunken Temples behind cheekbones
  for (let y = 15; y <= 18; y++) {
    for (let z = 8; z <= 12; z++) {
      for (let x = 4; x <= 5; x++) setBlock(x, y, z, null);
      for (let x = 20; x <= 21; x++) setBlock(x, y, z, null);
    }
  }

  // Hollow Watchtower Shafts
  for (let y = seatY + 1; y <= 27; y++) {
    for (let x = 3; x <= 7; x++) {
      for (let z = 16; z <= 20; z++) {
        if ((x - 5) ** 2 + (z - 18) ** 2 <= 1.8 ** 2) setBlock(x, y, z, null);
      }
    }
    for (let x = 18; x <= 22; x++) {
      for (let z = 16; z <= 20; z++) {
        if ((x - 20) ** 2 + (z - 18) ** 2 <= 1.8 ** 2) setBlock(x, y, z, null);
      }
    }
  }

  // 4. Floors & Structural Decks
  // Ground Floor Courtyard
  for (let x = 8; x <= 17; x++) {
    for (let z = 8; z <= 18; z++) {
      setBlock(x, seatY, z, groundPavement);
    }
  }
  for (let x = 10; x <= 15; x++) {
    for (let z = 1; z <= 8; z++) {
      setBlock(x, seatY, z, groundPavement);
    }
  }

  // Battery Deck Timber Floor (Y=14)
  for (let x = 6; x <= 19; x++) {
    for (let z = 6; z <= 19; z++) {
      const dx = (x - 12.5) / 8.5;
      const dz = (z - 14.0) / 8.0;
      if (dx * dx + dz * dz <= 1.0) {
        setBlock(x, 14, z, woodPlanks);
      }
    }
  }

  // Roof Battle Deck (Y=25) & Clear Headroom Above (Y>=26)
  for (let x = 5; x <= 20; x++) {
    for (let z = 7; z <= 21; z++) {
      const dx = (x - 12.5) / 8.0;
      const dz = (z - 14.0) / 7.5;
      if (dx * dx + dz * dz <= 1.0) {
        setBlock(x, 25, z, woodPlanks);
        for (let y = 26; y <= 30; y++) {
          setBlock(x, y, z, null);
        }
      }
    }
  }

  // 5. Skull Crenellations, Battlements, & Tower Tops
  // Roof Parapet ring around Cranium Deck
  for (let x = 4; x <= 21; x++) {
    for (let z = 6; z <= 22; z++) {
      const dx = (x - 12.5) / 8.2;
      const dz = (z - 14.0) / 7.8;
      const dist = dx * dx + dz * dz;
      if (dist >= 0.85 && dist <= 1.15) {
        setBlock(x, 26, z, stoneAccent);
        if ((x + z) % 2 === 0) {
          setBlock(x, 27, z, wallMerlon);
        } else {
          setBlock(x, 27, z, stonePrimary);
        }
      }
    }
  }

  // Tower battlements (Y=28..29)
  function buildTowerTop(cx, cz) {
    for (let x = cx - 3; x <= cx + 3; x++) {
      for (let z = cz - 3; z <= cz + 3; z++) {
        const d = (x - cx) ** 2 + (z - cz) ** 2;
        if (d <= 3.6 ** 2 && d > 2.0 ** 2) {
          setBlock(x, 27, z, stoneAccent);
          setBlock(x, 28, z, (x + z) % 2 === 0 ? wallMerlon : stonePrimary);
        } else if (d <= 2.0 ** 2) {
          setBlock(x, 27, z, woodPlanks);
          setBlock(x, 28, z, null);
          setBlock(x, 29, z, null);
        }
      }
    }
  }
  buildTowerTop(5, 18);
  buildTowerTop(20, 18);

  // 6. Staircases in Watchtowers
  for (let y = seatY + 1; y <= 14; y++) {
    setBlock(5, y, 18, woodLog);
    const step = (y - seatY) % 4;
    if (step === 0) setBlock(5, y, 17, woodStairs + "[facing=east]");
    if (step === 1) setBlock(6, y, 18, woodStairs + "[facing=south]");
    if (step === 2) setBlock(5, y, 19, woodStairs + "[facing=west]");
    if (step === 3) setBlock(4, y, 18, woodStairs + "[facing=north]");
  }
  for (let y = 14; y <= 27; y++) {
    setBlock(20, y, 18, woodLog);
    const step = (y - 14) % 4;
    if (step === 0) setBlock(20, y, 17, woodStairs + "[facing=east]");
    if (step === 1) setBlock(21, y, 18, woodStairs + "[facing=south]");
    if (step === 2) setBlock(20, y, 19, woodStairs + "[facing=west]");
    if (step === 3) setBlock(19, y, 18, woodStairs + "[facing=north]");
  }

  // 7. Architectural Detailing: Skull Teeth, Brow Ridge, & Portcullis
  // Upper Jaw Teeth (Y=9, Z=2)
  setBlock(10, 9, 2, stoneStairs + "[half=top,facing=south]");
  setBlock(11, 9, 2, stoneWall);
  setBlock(12, 9, 2, stoneStairs + "[half=top,facing=east]");
  setBlock(13, 9, 2, stoneStairs + "[half=top,facing=west]");
  setBlock(14, 9, 2, stoneWall);
  setBlock(15, 9, 2, stoneStairs + "[half=top,facing=south]");

  // Lower Jaw Teeth (Y=5, Z=2)
  setBlock(10, 5, 2, stoneStairs + "[half=bottom,facing=north]");
  setBlock(12, 5, 2, stoneWall);
  setBlock(13, 5, 2, stoneWall);
  setBlock(15, 5, 2, stoneStairs + "[half=bottom,facing=north]");

  // Heavy Brow Ridge Overhang (Y=20, Z=2..3)
  for (let x = 6; x <= 19; x++) {
    if ((x >= 6 && x <= 10) || (x >= 15 && x <= 19) || (x >= 12 && x <= 13)) {
      setBlock(x, 20, 2, stoneStairs + "[half=bottom,facing=north]");
      setBlock(x, 20, 3, stoneAccent);
    }
  }

  // Portcullis Grille in Mouth Gateway (Z=6)
  for (let x = 11; x <= 14; x++) {
    setBlock(x, 9, 6, woodFence);
    setBlock(x, 8, 6, woodFence);
    setBlock(x, 7, 6, woodFence);
  }

  // 8. Artillery Batteries Aimed Across Strait (-Z, North)
  // Left Eye Socket Cannon
  setBlock(8, 15, 5, woodPlanks);
  setBlock(8, 15, 6, woodStairs + "[facing=south]");
  setBlock(7, 15, 5, woodTrapdoor + "[facing=west,open=true]");
  setBlock(9, 15, 5, woodTrapdoor + "[facing=east,open=true]");
  setBlock(8, 16, 4, stoneAccent);
  setBlock(8, 16, 3, "minecraft:dispenser[facing=north]");
  setBlock(8, 17, 7, "minecraft:soul_wall_torch[facing=north]");

  // Right Eye Socket Cannon
  setBlock(17, 15, 5, woodPlanks);
  setBlock(17, 15, 6, woodStairs + "[facing=south]");
  setBlock(16, 15, 5, woodTrapdoor + "[facing=west,open=true]");
  setBlock(18, 15, 5, woodTrapdoor + "[facing=east,open=true]");
  setBlock(17, 16, 4, stoneAccent);
  setBlock(17, 16, 3, "minecraft:dispenser[facing=north]");
  setBlock(17, 17, 7, "minecraft:soul_wall_torch[facing=north]");

  // Roof Battle Deck Heavy Cannons
  // Left Roof Gun
  setBlock(8, 26, 8, woodPlanks);
  setBlock(8, 26, 9, woodStairs + "[facing=south]");
  setBlock(7, 26, 8, woodTrapdoor + "[facing=west,open=true]");
  setBlock(9, 26, 8, woodTrapdoor + "[facing=east,open=true]");
  setBlock(8, 26, 7, "minecraft:dispenser[facing=north]");

  // Right Roof Gun
  setBlock(17, 26, 8, woodPlanks);
  setBlock(17, 26, 9, woodStairs + "[facing=south]");
  setBlock(16, 26, 8, woodTrapdoor + "[facing=west,open=true]");
  setBlock(18, 26, 8, woodTrapdoor + "[facing=east,open=true]");
  setBlock(17, 26, 7, "minecraft:dispenser[facing=north]");

  // 9. Flagpole, Lookout Rigging, & Signal Beacon atop Cranium Deck
  for (let y = 26; y <= 31; y++) {
    setBlock(12, y, 14, woodStripped);
    setBlock(13, y, 14, woodStripped);
  }
  // Cross Spar Rigging
  for (let x = 10; x <= 15; x++) {
    setBlock(x, 29, 14, woodFence);
  }
  setBlock(10, 28, 14, "minecraft:lantern[hanging=true]");
  setBlock(15, 28, 14, "minecraft:lantern[hanging=true]");
  setBlock(12, 31, 14, woodFence);
  setBlock(13, 31, 14, woodFence);

  // 10. Emit all blocks from grid deterministically
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const blk = grid[x][y][z];
        if (blk !== null) {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  return {
    name: "pirate_skull_fort",
    seatY: seatY,
    anchors: {
      front: [12, seatY, 0],
      door: [12, seatY, 1],
      battery: [12, 15, 3],
      roof: [12, 26, 14]
    },
    interiors: [
      { min: [8, seatY + 1, 9], max: [17, 9, 18], kind: "hall" },
      { min: [7, 15, 8], max: [18, 19, 17], kind: "bridge" }
    ]
  };
}

arcane_ward_crystal.source:
export const envelope = [9, 17, 9];

export default function build(api) {
  const pStone = api.theme?.stone?.primary || "minecraft:smooth_quartz";
  const pAccent = api.theme?.stone?.accent || "minecraft:chiseled_quartz_block";
  const pStairs = api.theme?.stone?.stairs || "minecraft:smooth_quartz_stairs";
  const pSlab = api.theme?.stone?.slab || "minecraft:smooth_quartz_slab";
  const pPlinth = api.theme?.ground?.plinth || "minecraft:quartz_pillar[axis=y]";

  const AMETHYST = "minecraft:amethyst_block";
  const BUDDING = "minecraft:budding_amethyst";
  const CRYING = "minecraft:crying_obsidian";
  const OBSIDIAN = "minecraft:obsidian";
  const LANTERN = "minecraft:sea_lantern";
  const TINTED = "minecraft:tinted_glass";
  const MAGENTA_GLASS = "minecraft:magenta_stained_glass";
  const PURPLE_GLASS = "minecraft:purple_stained_glass";
  const QUARTZ_PILLAR = "minecraft:quartz_pillar[axis=y]";
  const CHISELED_QUARTZ = "minecraft:chiseled_quartz_block";
  const SMOOTH_QUARTZ = "minecraft:smooth_quartz";

  const END_ROD_UP = "minecraft:end_rod[facing=up]";
  const CLUSTER_UP = "minecraft:amethyst_cluster[facing=up]";
  const CLUSTER_N = "minecraft:amethyst_cluster[facing=north]";
  const CLUSTER_S = "minecraft:amethyst_cluster[facing=south]";
  const CLUSTER_E = "minecraft:amethyst_cluster[facing=east]";
  const CLUSTER_W = "minecraft:amethyst_cluster[facing=west]";

  function stair(facing, half = "bottom") {
    const baseName = pStairs.split("[")[0];
    return `${baseName}[facing=${facing},half=${half}]`;
  }

  function slab(type = "bottom") {
    const baseName = pSlab.split("[")[0];
    return `${baseName}[type=${type}]`;
  }

  const grid = new Map();

  function set(x, y, z, block) {
    if (x >= 0 && x < 9 && y >= 0 && y < 17 && z >= 0 && z < 9) {
      grid.set(`${x},${y},${z}`, block);
    }
  }

  function get(x, y, z) {
    return grid.get(`${x},${y},${z}`) || null;
  }

  function has(x, y, z) {
    return grid.has(`${x},${y},${z}`);
  }

  function placeSideCluster(x, y, z, dir) {
    if (!has(x, y, z)) {
      if (dir === "north" && has(x, y, z + 1)) set(x, y, z, CLUSTER_N);
      else if (dir === "south" && has(x, y, z - 1)) set(x, y, z, CLUSTER_S);
      else if (dir === "west" && has(x + 1, y, z)) set(x, y, z, CLUSTER_W);
      else if (dir === "east" && has(x - 1, y, z)) set(x, y, z, CLUSTER_E);
      else if (dir === "up" && has(x, y - 1, z)) set(x, y, z, CLUSTER_UP);
    }
  }

  const variant = (api.instance?.index ?? 0) % 6;

  // -------------------------------------------------------------------------
  // 1. FOUNDATION & DAIS (Layers y = 0 to 4)
  // -------------------------------------------------------------------------
  // Layer y = 0: Grand 9x9 runic plinth (77 blocks)
  for (let x = 0; x <= 8; x++) {
    for (let z = 0; z <= 8; z++) {
      const dx = Math.abs(x - 4);
      const dz = Math.abs(z - 4);
      // Omit only extreme 4 corners
      if (dx === 4 && dz === 4) continue;

      let b = pStone;
      const r = Math.sqrt(dx * dx + dz * dz);
      if (r < 1.5) {
        b = AMETHYST;
      } else if (r >= 1.5 && r <= 3.2) {
        b = (dx === dz || dx === 0 || dz === 0) ? CRYING : pAccent;
      } else {
        b = pPlinth;
      }
      set(x, 0, z, b);
    }
  }

  // Layer y = 1: Stepped dais with perimeter stairs & rune inlay (61 blocks)
  for (let x = 1; x <= 7; x++) {
    for (let z = 1; z <= 7; z++) {
      const dx = Math.abs(x - 4);
      const dz = Math.abs(z - 4);
      if (dx === 3 && dz === 3) continue;

      let b = pStone;
      if (dx === 3) {
        b = (x === 1) ? stair("east") : stair("west");
      } else if (dz === 3) {
        b = (z === 1) ? stair("south") : stair("north");
      } else {
        const r = Math.sqrt(dx * dx + dz * dz);
        if (r < 1.5) b = pAccent;
        else if (r <= 2.5) b = (dx === 0 || dz === 0) ? CRYING : AMETHYST;
        else b = pStone;
      }
      set(x, 1, z, b);
    }
  }
  // Cardinal step extensions on y = 1
  set(4, 1, 0, stair("south"));
  set(4, 1, 8, stair("north"));
  set(0, 1, 4, stair("east"));
  set(8, 1, 4, stair("west"));

  // Layer y = 2: Upper Altar Tier & Shard sockets (37 blocks)
  for (let x = 2; x <= 6; x++) {
    for (let z = 2; z <= 6; z++) {
      const dx = Math.abs(x - 4);
      const dz = Math.abs(z - 4);
      if (dx === 2 && dz === 2) {
        set(x, 2, z, pAccent);
      } else if (dx === 2 || dz === 2) {
        if (dx === 2 && x === 2) set(x, 2, z, stair("east"));
        else if (dx === 2 && x === 6) set(x, 2, z, stair("west"));
        else if (dz === 2 && z === 2) set(x, 2, z, stair("south"));
        else if (dz === 2 && z === 6) set(x, 2, z, stair("north"));
      } else {
        set(x, 2, z, (dx === 0 && dz === 0) ? LANTERN : CRYING);
      }
    }
  }
  // 4 Outer Shard Pedestals on y = 2
  set(4, 2, 1, CRYING);
  set(4, 2, 7, CRYING);
  set(1, 2, 4, CRYING);
  set(7, 2, 4, CRYING);
  set(2, 2, 2, pAccent);
  set(6, 2, 2, pAccent);
  set(2, 2, 6, pAccent);
  set(6, 2, 6, pAccent);

  // Layer y = 3: Pedestal core & Shard roots (29 blocks)
  for (let x = 2; x <= 6; x++) {
    for (let z = 2; z <= 6; z++) {
      const dx = Math.abs(x - 4);
      const dz = Math.abs(z - 4);
      if (dx <= 1 && dz <= 1) {
        set(x, 3, z, (dx === 0 || dz === 0) ? AMETHYST : CRYING);
      }
    }
  }
  set(4, 3, 1, QUARTZ_PILLAR);
  set(4, 3, 7, QUARTZ_PILLAR);
  set(1, 3, 4, QUARTZ_PILLAR);
  set(7, 3, 4, QUARTZ_PILLAR);
  set(2, 3, 2, CRYING);
  set(6, 3, 2, CRYING);
  set(2, 3, 6, CRYING);
  set(6, 3, 6, CRYING);

  // Layer y = 4: Crystal Socket & Lower Shard Columns (25 blocks)
  for (let x = 3; x <= 5; x++) {
    for (let z = 3; z <= 5; z++) {
      set(x, 4, z, (x === 4 && z === 4) ? BUDDING : AMETHYST);
    }
  }
  set(4, 4, 1, AMETHYST);
  set(4, 4, 7, AMETHYST);
  set(1, 4, 4, AMETHYST);
  set(7, 4, 4, AMETHYST);
  set(2, 4, 2, pStone);
  set(6, 4, 2, pStone);
  set(2, 4, 6, pStone);
  set(6, 4, 6, pStone);

  // -------------------------------------------------------------------------
  // 2. VARIANT SPECIFIC UPPER CRYSTAL SPIRES & HOVERING SHARDS (y = 5 to 16)
  // -------------------------------------------------------------------------

  if (variant === 0) {
    // --- VARIANT 0: The Zenith Sanctuary Ward (Pristine High-Ward) ---
    // Core crystal with glowing lantern core encased in tinted glass
    for (let y = 5; y <= 7; y++) {
      set(4, y, 4, LANTERN);
      set(3, y, 4, TINTED);
      set(5, y, 4, TINTED);
      set(4, y, 3, TINTED);
      set(4, y, 5, TINTED);
      set(3, y, 3, AMETHYST);
      set(5, y, 3, AMETHYST);
      set(3, y, 5, AMETHYST);
      set(5, y, 5, AMETHYST);
    }
    // Middle faceted spire
    for (let y = 8; y <= 10; y++) {
      set(4, y, 4, AMETHYST);
      set(3, y, 4, BUDDING);
      set(5, y, 4, BUDDING);
      set(4, y, 3, BUDDING);
      set(4, y, 5, BUDDING);
    }
    // Tapering crystal tip
    for (let y = 11; y <= 13; y++) {
      set(4, y, 4, AMETHYST);
      if (y === 11) {
        set(3, y, 4, AMETHYST);
        set(5, y, 4, AMETHYST);
        set(4, y, 3, AMETHYST);
        set(4, y, 5, AMETHYST);
      }
    }
    set(4, 14, 4, BUDDING);
    set(4, 15, 4, AMETHYST);
    set(4, 16, 4, CLUSTER_UP);

    // 4 Cardinal Shards and Energy Arcs
    const shards = [[4, 1], [4, 7], [1, 4], [7, 4]];
    shards.forEach(([sx, sz]) => {
      for (let y = 5; y <= 8; y++) {
        set(sx, y, sz, (y % 2 === 0) ? AMETHYST : CRYING);
      }
      set(sx, 9, sz, AMETHYST);
      set(sx, 10, sz, CLUSTER_UP);
    });

    // Arcane bridges (y = 6 to 8)
    for (let y = 6; y <= 8; y++) {
      set(4, y, 2, MAGENTA_GLASS);
      set(4, y, 6, MAGENTA_GLASS);
      set(2, y, 4, MAGENTA_GLASS);
      set(6, y, 4, MAGENTA_GLASS);
    }

  } else if (variant === 1) {
    // --- VARIANT 1: The Diamond Aegis (Diagonal Bastion Spire) ---
    // Diamond core
    for (let y = 5; y <= 8; y++) {
      set(4, y, 4, LANTERN);
      set(4, y, 3, AMETHYST);
      set(4, y, 5, AMETHYST);
      set(3, y, 4, AMETHYST);
      set(5, y, 4, AMETHYST);
      set(3, y, 3, PURPLE_GLASS);
      set(5, y, 3, PURPLE_GLASS);
      set(3, y, 5, PURPLE_GLASS);
      set(5, y, 5, PURPLE_GLASS);
    }
    for (let y = 9; y <= 12; y++) {
      set(4, y, 4, BUDDING);
      set(3, y, 3, AMETHYST);
      set(5, y, 3, AMETHYST);
      set(3, y, 5, AMETHYST);
      set(5, y, 5, AMETHYST);
    }
    for (let y = 13; y <= 15; y++) {
      set(4, y, 4, AMETHYST);
    }
    set(4, 16, 4, END_ROD_UP);

    // 4 Diagonal Shard Towers
    const diagShards = [[2, 2], [6, 2], [2, 6], [6, 6]];
    diagShards.forEach(([sx, sz]) => {
      for (let y = 5; y <= 9; y++) {
        set(sx, y, sz, (y === 7) ? LANTERN : AMETHYST);
      }
      set(sx, 10, sz, BUDDING);
      set(sx, 11, sz, CLUSTER_UP);
    });

    // Diagonal flying energy arcs (y = 6 to 8)
    for (let y = 6; y <= 8; y++) {
      set(3, y, 3, TINTED);
      set(5, y, 3, TINTED);
      set(3, y, 5, TINTED);
      set(5, y, 5, TINTED);
    }

  } else if (variant === 2) {
    // --- VARIANT 2: The Besieged Bulwark (Pirate Artillery Impact Scar) ---
    // North side is blasted / cracked by pirate cannons
    set(4, 0, 1, OBSIDIAN);
    set(4, 1, 1, CRYING);
    set(3, 1, 1, OBSIDIAN);
    set(5, 1, 1, CRYING);

    // Tilted crystal core (deflected toward South-East)
    for (let y = 5; y <= 7; y++) {
      set(4, y, 4, LANTERN);
      set(4, y, 3, (y === 6) ? MAGENTA_GLASS : CRYING); // Shattered north face
      set(5, y, 4, AMETHYST);
      set(4, y, 5, AMETHYST);
      set(3, y, 4, AMETHYST);
      set(5, y, 5, BUDDING);
    }
    for (let y = 8; y <= 11; y++) {
      set(5, y, 5, AMETHYST);
      set(4, y, 5, BUDDING);
      set(5, y, 4, CRYING);
      set(4, y, 4, TINTED);
    }
    for (let y = 12; y <= 15; y++) {
      set(5, y, 5, (y % 2 === 0) ? AMETHYST : BUDDING);
    }
    set(5, 16, 5, CLUSTER_UP);

    // North shard is severed/shattered
    set(4, 5, 1, CRYING);
    set(4, 6, 1, OBSIDIAN);

    // Intact South, East, West shards are overcharging to compensate
    const intactShards = [[4, 7], [1, 4], [7, 4]];
    intactShards.forEach(([sx, sz]) => {
      for (let y = 5; y <= 10; y++) {
        set(sx, y, sz, (y === 7) ? LANTERN : AMETHYST);
      }
      set(sx, 11, sz, END_ROD_UP);
    });

    // Surge conduits to the tilted spire
    for (let y = 7; y <= 9; y++) {
      set(4, y, 6, MAGENTA_GLASS);
      set(6, y, 4, MAGENTA_GLASS);
      set(2, y, 4, MAGENTA_GLASS);
    }

  } else if (variant === 3) {
    // --- VARIANT 3: The Seraphic Twin Needle (Harmonic Bifurcation) ---
    // Monolithic trunk
    for (let y = 5; y <= 8; y++) {
      set(4, y, 4, (y === 7) ? LANTERN : AMETHYST);
      set(3, y, 4, CHISELED_QUARTZ);
      set(5, y, 4, CHISELED_QUARTZ);
      set(4, y, 3, CRYING);
      set(4, y, 5, CRYING);
    }
    // Splitting platform
    set(3, 9, 4, AMETHYST);
    set(4, 9, 4, BUDDING);
    set(5, 9, 4, AMETHYST);

    // Twin Spire West
    for (let y = 10; y <= 15; y++) {
      set(3, y, 4, (y % 2 === 0) ? AMETHYST : BUDDING);
    }
    set(3, 16, 4, CLUSTER_UP);

    // Twin Spire East
    for (let y = 10; y <= 15; y++) {
      set(5, y, 4, (y % 2 === 1) ? AMETHYST : BUDDING);
    }
    set(5, 16, 4, END_ROD_UP);

    // Harmonic glass lattice connecting the two needles
    set(4, 11, 4, TINTED);
    set(4, 13, 4, TINTED);

    // 4 Wing-like Shards
    const shards = [[4, 1], [4, 7], [1, 4], [7, 4]];
    shards.forEach(([sx, sz]) => {
      for (let y = 5; y <= 9; y++) {
        set(sx, y, sz, AMETHYST);
      }
      set(sx, 10, sz, BUDDING);
      set(sx, 11, sz, CLUSTER_UP);
    });

    // Quartz flying buttresses (y = 6 to 8)
    for (let y = 6; y <= 8; y++) {
      set(4, y, 2, SMOOTH_QUARTZ);
      set(4, y, 6, SMOOTH_QUARTZ);
      set(2, y, 4, SMOOTH_QUARTZ);
      set(6, y, 4, SMOOTH_QUARTZ);
    }

  } else if (variant === 4) {
    // --- VARIANT 4: The Crying Rune Monolith (Heavy Arcane Battery) ---
    // Massive octagonal crystal core
    for (let y = 5; y <= 9; y++) {
      set(4, y, 4, (y === 7) ? LANTERN : AMETHYST);
      set(3, y, 4, CRYING);
      set(5, y, 4, CRYING);
      set(4, y, 3, CRYING);
      set(4, y, 5, CRYING);
      set(3, y, 3, TINTED);
      set(5, y, 3, TINTED);
      set(3, y, 5, TINTED);
      set(5, y, 5, TINTED);
    }
    for (let y = 10; y <= 13; y++) {
      set(4, y, 4, BUDDING);
      set(3, y, 4, AMETHYST);
      set(5, y, 4, AMETHYST);
      set(4, y, 3, AMETHYST);
      set(4, y, 5, AMETHYST);
    }
    set(4, 14, 4, AMETHYST);
    set(4, 15, 4, BUDDING);
    set(4, 16, 4, CLUSTER_UP);

    // Thick double-block cardinal pylons
    const pylons = [
      [[4, 1], [3, 1]],
      [[4, 7], [5, 7]],
      [[1, 4], [1, 5]],
      [[7, 4], [7, 3]]
    ];
    pylons.forEach(([p1, p2]) => {
      for (let y = 5; y <= 9; y++) {
        set(p1[0], y, p1[1], (y % 2 === 0) ? AMETHYST : CRYING);
        set(p2[0], y, p2[1], (y % 2 === 1) ? AMETHYST : CRYING);
      }
      set(p1[0], 10, p1[1], BUDDING);
      set(p1[0], 11, p1[1], CLUSTER_UP);
    });

    // Double solid energy beams at y = 5 and y = 9
    [5, 9].forEach(y => {
      set(4, y, 2, CRYING);
      set(4, y, 6, CRYING);
      set(2, y, 4, CRYING);
      set(6, y, 4, CRYING);
    });

  } else {
    // --- VARIANT 5: The Starlight Corona (Helical Spiral Spire) ---
    // Spiral energy core
    const spiralOffsets = [
      [[3, 4], [5, 4]], // y=5
      [[3, 3], [5, 5]], // y=6
      [[4, 3], [4, 5]], // y=7
      [[5, 3], [3, 5]], // y=8
      [[5, 4], [3, 4]], // y=9
      [[5, 5], [3, 3]], // y=10
      [[4, 5], [4, 3]]  // y=11
    ];

    for (let y = 5; y <= 11; y++) {
      set(4, y, 4, (y % 2 === 0) ? LANTERN : AMETHYST);
      const [f1, f2] = spiralOffsets[y - 5];
      set(f1[0], y, f1[1], MAGENTA_GLASS);
      set(f2[0], y, f2[1], PURPLE_GLASS);
    }
    for (let y = 12; y <= 14; y++) {
      set(4, y, 4, BUDDING);
      if (y === 12) {
        set(4, y, 3, AMETHYST);
        set(4, y, 5, AMETHYST);
      }
    }
    set(4, 15, 4, AMETHYST);
    set(4, 16, 4, END_ROD_UP);

    // Staggered height corona shards
    const coronaShards = [
      { pos: [4, 1], h: 9, crown: CLUSTER_UP },
      { pos: [7, 4], h: 12, crown: END_ROD_UP },
      { pos: [4, 7], h: 10, crown: CLUSTER_UP },
      { pos: [1, 4], h: 11, crown: END_ROD_UP }
    ];

    coronaShards.forEach(({ pos: [sx, sz], h, crown }) => {
      for (let y = 5; y < h; y++) {
        set(sx, y, sz, (y === 7) ? LANTERN : AMETHYST);
      }
      set(sx, h, sz, BUDDING);
      set(sx, h + 1, sz, crown);
    });

    // Translucent spiral ribbons linking corona shards to center
    set(4, 6, 2, TINTED);
    set(6, 7, 4, TINTED);
    set(4, 8, 6, TINTED);
    set(2, 9, 4, TINTED);
  }

  // -------------------------------------------------------------------------
  // 3. DECORATIVE AMETHYST CLUSTERS & RESONANT BUDS
  // -------------------------------------------------------------------------
  // Add resonant clusters to exterior facets
  placeSideCluster(4, 5, 0, "north");
  placeSideCluster(4, 5, 8, "south");
  placeSideCluster(0, 5, 4, "west");
  placeSideCluster(8, 5, 4, "east");

  placeSideCluster(4, 8, 0, "north");
  placeSideCluster(4, 8, 8, "south");
  placeSideCluster(0, 8, 4, "west");
  placeSideCluster(8, 8, 4, "east");

  if (api.random() > 0.4) placeSideCluster(3, 10, 4, "west");
  if (api.random() > 0.4) placeSideCluster(5, 10, 4, "east");
  if (api.random() > 0.4) placeSideCluster(4, 10, 3, "north");
  if (api.random() > 0.4) placeSideCluster(4, 10, 5, "south");

  // -------------------------------------------------------------------------
  // 4. DETERMINISTIC EMISSION
  // -------------------------------------------------------------------------
  for (let y = 0; y < 17; y++) {
    for (let z = 0; z < 9; z++) {
      for (let x = 0; x < 9; x++) {
        const k = `${x},${y},${z}`;
        if (grid.has(k)) {
          api.set(x, y, z, grid.get(k));
        }
      }
    }
  }

  return {
    name: "arcane_ward_crystal",
    seatY: 0,
    anchors: {
      front: [4, 1, 0],
      core: [4, 8, 4]
    }
  };
}

corsair_cannon_battery.source:
export const envelope = [13, 9, 11];

export default function build(api) {
  const { index } = api.instance;
  const rng = () => api.random();

  const grid = new Map();
  function place(x, y, z, block) {
    if (x >= 0 && x < 13 && y >= 0 && y < 9 && z >= 0 && z < 11) {
      grid.set(`${x},${y},${z}`, { x, y, z, block });
    }
  }

  // Palette with safe theme resolution
  function withState(blockStr, state) {
    if (!blockStr) return state ? `minecraft:stone[${state}]` : "minecraft:stone";
    const base = blockStr.split("[")[0];
    return state ? `${base}[${state}]` : base;
  }

  const woodPlanks = api.theme?.wood?.planks ?? "minecraft:dark_oak_planks";
  const woodLog = api.theme?.wood?.log ?? "minecraft:dark_oak_log";
  const woodStripped = api.theme?.wood?.stripped ?? "minecraft:stripped_dark_oak_log";
  const woodStairs = api.theme?.wood?.stairs ?? "minecraft:dark_oak_stairs";
  const woodSlab = api.theme?.wood?.slab ?? "minecraft:dark_oak_slab";
  const woodFence = api.theme?.wood?.fence ?? "minecraft:dark_oak_fence";
  const woodTrapdoor = api.theme?.wood?.trapdoor ?? "minecraft:dark_oak_trapdoor";

  const stonePrimary = api.theme?.stone?.primary ?? "minecraft:cobblestone";
  const stoneAccent = api.theme?.stone?.accent ?? "minecraft:mossy_cobblestone";
  const stoneStairs = api.theme?.stone?.stairs ?? "minecraft:cobblestone_stairs";
  const stoneSlab = api.theme?.stone?.slab ?? "minecraft:cobblestone_slab";
  const stoneWall = api.theme?.stone?.wall ?? "minecraft:cobblestone_wall";
  const groundPlinth = api.theme?.ground?.plinth ?? "minecraft:stone_bricks";

  // Per-instance structural & combat variations
  const mastOnLeft = index % 2 === 0;
  const mastX = mastOnLeft ? 1 : 11;
  const shelterX1 = mastOnLeft ? 9 : 1;
  const shelterX2 = mastOnLeft ? 11 : 3;

  const leftGunState = index % 3; // 0: run-out, 1: recoiled/reloading, 2: heavy mortar
  const rightGunState = (index + 1) % 3; // 0: run-out, 1: recoiled, 2: ready long gun

  const damagedMerlon = index === 2 || index === 4;
  const deckScorched = index === 1 || index === 5;

  // 1. Foundation, Sub-deck, and Gun Deck Platform (y = 0..2)
  for (let x = 0; x <= 12; x++) {
    for (let z = 0; z <= 8; z++) {
      // Solid plinth & foundation
      const isPerimeter = x === 0 || x === 12 || z === 0;
      const isPiling = isPerimeter && (x % 2 === 0 || z % 2 === 0);

      const baseBlock = isPiling ? withState(woodLog, "axis=y") : (rng() < 0.25 ? stoneAccent : groundPlinth);
      place(x, 0, z, baseBlock);

      const midBlock = isPerimeter ? (rng() < 0.3 ? stoneAccent : stonePrimary) : stonePrimary;
      place(x, 1, z, midBlock);

      // Deck surface (y = 2)
      if (isPerimeter) {
        place(x, 2, z, isPiling ? withState(woodLog, "axis=y") : stonePrimary);
      } else {
        let deckBlock = woodPlanks;
        if (deckScorched && ((x === 3 && z === 4) || (x === 9 && z === 4))) {
          deckBlock = "minecraft:basalt[axis=y]";
        } else if (rng() < 0.15) {
          deckBlock = withState(woodStripped, "axis=z");
        }
        place(x, 2, z, deckBlock);
      }
    }
  }

  // 2. Rear Access Ramp & Steps (x = 5..7, z = 8..10)
  for (let x = 5; x <= 7; x++) {
    place(x, 0, 9, stonePrimary);
    place(x, 1, 9, withState(woodStairs, "facing=south,half=bottom"));
    place(x, 0, 10, withState(woodStairs, "facing=south,half=bottom"));
  }
  // Stair handrails
  place(4, 1, 9, withState(woodLog, "axis=y"));
  place(4, 2, 9, woodFence);
  place(8, 1, 9, withState(woodLog, "axis=y"));
  place(8, 2, 9, woodFence);

  // 3. Flank Walls & Parapets (x = 0 and x = 12, z = 1..8)
  for (const fx of [0, 12]) {
    for (let z = 1; z <= 8; z++) {
      place(fx, 3, z, (z % 2 === 1) ? withState(woodLog, "axis=y") : stonePrimary);
      if (z % 2 === 0) {
        place(fx, 4, z, stoneWall);
      } else {
        place(fx, 4, z, withState(woodSlab, "type=bottom"));
      }
    }
  }

  // 4. Front Rampart & Sandbag Embrasures (z = 0..1, y = 2..5)
  // Front seaward ledges at z = 0
  for (let x = 0; x <= 12; x++) {
    if (x === 0 || x === 1 || x === 5 || x === 6 || x === 7 || x === 11 || x === 12) {
      place(x, 3, 0, withState(stoneSlab, "type=bottom"));
    }
  }

  // Main Rampart at z = 1
  for (let x = 0; x <= 12; x++) {
    const isLeftEmbrasure = (x === 3);
    const isRightEmbrasure = (x === 9);

    if (isLeftEmbrasure || isRightEmbrasure) {
      // Open firing embrasures
      place(x, 3, 1, withState(stoneSlab, "type=bottom"));
      // Cheeks of embrasure
      place(x - 1, 3, 1, "minecraft:mud_bricks");
      place(x + 1, 3, 1, "minecraft:mud_bricks");
      place(x - 1, 4, 1, "minecraft:mud_brick_slab[type=bottom]");
      place(x + 1, 4, 1, "minecraft:mud_brick_slab[type=bottom]");
    } else if (x === 0 || x === 1 || x === 5 || x === 6 || x === 7 || x === 11 || x === 12) {
      // Solid sandbag / timber rampart
      place(x, 3, 1, (x === 6) ? "minecraft:smooth_sandstone" : "minecraft:mud_bricks");
      if (!(damagedMerlon && x === 11)) {
        place(x, 4, 1, (x === 6) ? "minecraft:packed_mud" : "minecraft:mud_bricks");
      } else {
        place(x, 4, 1, withState(stoneSlab, "type=bottom"));
      }
      if (x === 6) {
        place(x, 5, 1, "minecraft:mud_brick_slab[type=bottom]");
      }
    }
  }

  // Central Traverse Blast Wall (x = 6, z = 2..4)
  for (let z = 2; z <= 4; z++) {
    place(6, 3, z, "minecraft:mud_bricks");
    place(6, 4, z, (z === 2) ? "minecraft:mud_brick_slab[type=bottom]" : "minecraft:packed_mud");
  }

  // 5. Left Cannon Installation (Centered at x = 3)
  const leftZ = (leftGunState === 1) ? 2 : 1; // Recoiled or Run-out
  // Carriage cheeks & wheels
  place(2, 3, leftZ, withState(woodStairs, "facing=east,half=bottom"));
  place(2, 3, leftZ + 2, withState(woodStairs, "facing=east,half=bottom"));
  place(1, 3, leftZ, withState(woodTrapdoor, "facing=west,open=true"));
  place(1, 3, leftZ + 2, withState(woodTrapdoor, "facing=west,open=true"));

  place(4, 3, leftZ, withState(woodStairs, "facing=west,half=bottom"));
  place(4, 3, leftZ + 2, withState(woodStairs, "facing=west,half=bottom"));
  place(5, 3, leftZ, withState(woodTrapdoor, "facing=east,open=true"));
  place(5, 3, leftZ + 2, withState(woodTrapdoor, "facing=east,open=true"));

  // Carriage bed
  place(3, 3, leftZ, withState(woodStairs, "facing=north,half=bottom"));
  place(3, 3, leftZ + 1, woodPlanks);
  place(3, 3, leftZ + 2, withState(woodStairs, "facing=south,half=bottom"));

  // Iron Gun Barrel
  if (leftGunState === 0) {
    // Run-out standard long gun
    place(3, 4, 0, "minecraft:hopper[facing=north]");
    place(3, 4, 1, "minecraft:iron_block");
    place(3, 4, 2, "minecraft:iron_block");
    place(3, 4, 3, "minecraft:dispenser[facing=north]");
  } else if (leftGunState === 1) {
    // Recoiled & reloading
    place(3, 4, 1, "minecraft:iron_block");
    place(3, 4, 2, "minecraft:iron_block");
    place(3, 4, 3, "minecraft:iron_block");
    place(3, 4, 4, "minecraft:dispenser[facing=north]");
    // Rammer sponge post
    place(2, 3, 1, woodFence);
    place(2, 4, 1, woodFence);
  } else {
    // Heavy Carronade / Siege Mortar
    place(3, 4, 0, "minecraft:hopper[facing=north]");
    place(3, 4, 1, "minecraft:cauldron");
    place(3, 4, 2, "minecraft:iron_block");
    place(3, 4, 3, "minecraft:dispenser[facing=north]");
  }

  // 6. Right Cannon Installation (Centered at x = 9)
  const rightZ = (rightGunState === 1) ? 2 : 1;
  place(8, 3, rightZ, withState(woodStairs, "facing=east,half=bottom"));
  place(8, 3, rightZ + 2, withState(woodStairs, "facing=east,half=bottom"));
  place(7, 3, rightZ, withState(woodTrapdoor, "facing=west,open=true"));
  place(7, 3, rightZ + 2, withState(woodTrapdoor, "facing=west,open=true"));

  place(10, 3, rightZ, withState(woodStairs, "facing=west,half=bottom"));
  place(10, 3, rightZ + 2, withState(woodStairs, "facing=west,half=bottom"));
  place(11, 3, rightZ, withState(woodTrapdoor, "facing=east,open=true"));
  place(11, 3, rightZ + 2, withState(woodTrapdoor, "facing=east,open=true"));

  place(9, 3, rightZ, withState(woodStairs, "facing=north,half=bottom"));
  place(9, 3, rightZ + 1, woodPlanks);
  place(9, 3, rightZ + 2, withState(woodStairs, "facing=south,half=bottom"));

  if (rightGunState === 1) {
    place(9, 4, 1, "minecraft:iron_block");
    place(9, 4, 2, "minecraft:iron_block");
    place(9, 4, 3, "minecraft:iron_block");
    place(9, 4, 4, "minecraft:dispenser[facing=north]");
    place(10, 3, 1, woodFence);
    place(10, 4, 1, woodFence);
  } else {
    place(9, 4, 0, "minecraft:hopper[facing=north]");
    place(9, 4, 1, "minecraft:iron_block");
    place(9, 4, 2, "minecraft:iron_block");
    place(9, 4, 3, "minecraft:dispenser[facing=north]");
  }

  // 7. Rigging Mast, Lookout Spar & Corsair Battle Ensign (Reaches y = 8)
  for (let y = 2; y <= 7; y++) {
    place(mastX, y, 7, withState(woodLog, "axis=y"));
  }
  place(mastX, 8, 7, woodFence);

  // Cross-spar & rigging at y = 6
  place(mastX - 1, 6, 7, woodFence);
  place(mastX + 1, 6, 7, woodFence);
  place(mastX - 1, 5, 7, "minecraft:lantern[hanging=true]");

  // Crow's nest / Lookout at y = 7
  place(mastX, 7, 6, withState(woodTrapdoor, "facing=south,half=top,open=false"));
  place(mastX, 7, 8, withState(woodTrapdoor, "facing=north,half=top,open=false"));

  // Corsair Battle Flags (varied across instances)
  const flagColors = [
    ["minecraft:black_wool", "minecraft:white_wool"], // Jolly Roger
    ["minecraft:red_wool", "minecraft:black_wool"],     // Blood Flag (No Quarter)
    ["minecraft:yellow_wool", "minecraft:black_wool"],  // Gold & Sable Corsair
    ["minecraft:red_wool", "minecraft:white_wool"],     // Crimson Cross
    ["minecraft:black_wool", "minecraft:red_wool"],     // Black & Crimson split
    ["minecraft:black_wool", "minecraft:gray_wool"],    // Weathered Battle Ensign
  ][index % 6];

  place(mastX, 8, 6, flagColors[0]);
  place(mastX, 8, 5, flagColors[1]);
  place(mastX, 7, 5, flagColors[0]);

  // 8. Powder Storage Shelter & Munitions Depot (Opposite side of mast)
  // Support posts
  place(shelterX1, 3, 5, woodFence);
  place(shelterX1, 4, 5, woodFence);
  place(shelterX2, 3, 5, woodFence);
  place(shelterX2, 4, 5, woodFence);

  // Canopy roof (y = 5)
  for (let sx = Math.min(shelterX1, shelterX2); sx <= Math.max(shelterX1, shelterX2); sx++) {
    for (let sz = 5; sz <= 7; sz++) {
      place(sx, 5, sz, withState(woodSlab, "type=bottom"));
    }
  }

  // Powder Kegs, Barrels, and Shell Stacks inside shelter
  const midShelterX = Math.floor((shelterX1 + shelterX2) / 2);
  place(midShelterX, 3, 6, "minecraft:tnt");
  place(midShelterX, 4, 6, "minecraft:barrel[facing=up]");
  place(midShelterX + (mastOnLeft ? 1 : -1), 3, 6, "minecraft:barrel[facing=north]");
  place(midShelterX, 3, 7, "minecraft:barrel[facing=up]");
  place(midShelterX + (mastOnLeft ? 1 : -1), 3, 7, "minecraft:tnt");

  // Sponge & Wash Tub Cauldron on battery deck
  const tubX = mastOnLeft ? 1 : 11;
  place(tubX, 3, 3, "minecraft:cauldron");

  // Central Command Table & Signal Lantern (x = 6, z = 5..6)
  place(6, 3, 5, "minecraft:barrel[facing=up]");
  place(6, 4, 5, "minecraft:lantern[hanging=false]");
  place(6, 3, 6, withState(woodPlanks, ""));
  place(6, 4, 6, stoneWall);

  // Emit all placed blocks in deterministic sorted order
  const entries = Array.from(grid.values());
  entries.sort((a, b) => (a.y - b.y) || (a.z - b.z) || (a.x - b.x));
  for (const { x, y, z, block } of entries) {
    api.set(x, y, z, block);
  }

  return {
    name: "Corsair Cannon Battery",
    seatY: 0,
    anchors: {
      front: [6, 2, 0],
      entry: [6, 0, 10],
    },
  };
}
